<?php
namespace App\Http\Controllers;
use App\Models\User;
use App\Services\{Settings,MailAutomation};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash,Password,RateLimiter};
use Illuminate\Support\Str;
class AuthController extends Controller {
 public function page(Request $r,string $mode='login'){return response()->view('auth',['mode'=>$mode,'token'=>$r->route('token'),'email'=>$r->query('email',''),'action'=>$mode==='owner'?'/'.$r->path():'/'.$mode])->header('X-Robots-Tag','noindex, nofollow')->cookie('cvtara-device',$r->cookie('cvtara-device')?:bin2hex(random_bytes(32)),525600,'/',null,$r->isSecure(),true,false,'Lax');}
 public function register(Request $r){$r->merge(['email'=>strtolower(trim((string)$r->input('email')))]);$v=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users','password'=>'required|string|min:12|max:200|confirmed','experienceLevel'=>'required|in:fresher,experienced','profession'=>'required|string|max:120','category'=>'required|string|max:100','terms'=>'accepted'],['password.confirmed'=>'The two passwords do not match. Type the same password in both boxes.','password.min'=>'Use at least 12 characters for your password.','email.unique'=>'An account with this email already exists. Sign in instead, or use Forgot password.','email.email'=>'Enter a valid email address, like you@example.com.','terms.accepted'=>'Please accept the terms to create your account.','name.required'=>'Enter your full name.','profession.required'=>'Tell us the role you are aiming for.']);$u=DB::transaction(function()use($v,$r){$u=User::create(['name'=>$v['name'],'email'=>strtolower($v['email']),'password'=>Hash::make($v['password'])]);$u->forceFill(['referral_code'=>Str::random(16)])->save();$code=$r->session()->get('referral.code')??$r->cookie('cvtara_ref');$at=$r->session()->get('referral.at')??($code?time():null);$ref=$code&&$at&&now()->subDays(30)->timestamp<$at?User::where('referral_code',$code)->where('blocked',false)->first():null;if($ref&&$ref->id!==$u->id)$u->forceFill(['referred_by'=>$ref->id,'referral_attached_at'=>now()])->save();DB::table('profiles')->insert(['owner_id'=>$u->id,'name'=>$v['name'],'experience_level'=>$v['experienceLevel'],'profession'=>$v['profession'],'category'=>$v['category'],'onboarding_done'=>true,'marketing_consent'=>$r->boolean('marketing'),'created_at'=>now(),'updated_at'=>now()]);return $u;});Auth::login($u);$r->session()->regenerate();MailAutomation::queue($u,'profile_created','signup');Settings::audit($u->id,'registered');$next=(string)$r->input('next','');if(\App\Services\EmailVerification::required($u)){\App\Services\EmailVerification::send($u);$safe=$next!==''&&str_starts_with($next,'/')&&!str_starts_with($next,'//')&&!str_contains($next,'\\')&&!str_starts_with($next,'/admin');return redirect('/verify-email'.($safe?'?next='.urlencode($next):''));}if($next!==''&&str_starts_with($next,'/')&&!str_starts_with($next,'//')&&!str_contains($next,'\\')&&!preg_match('/[\\x00-\\x1f\\x7f]|%0[0-9a-f]|%2f|%5c/i',$next)&&!str_starts_with($next,'/admin'))return redirect($next);return redirect('/workspace.html?view=resumes');}
 public function ownerLogin(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);$key='owner-login:'.sha1(strtolower($v['email']).'|'.$r->ip());if(RateLimiter::tooManyAttempts($key,5))return back()->withErrors(['email'=>'Too many attempts. Try again in 15 minutes.']);if(!Auth::attempt(['email'=>strtolower($v['email']),'password'=>$v['password'],'blocked'=>false,'is_admin'=>true],false)){RateLimiter::hit($key,900);return back()->withErrors(['email'=>'Email or password is incorrect.']);}RateLimiter::clear($key);$r->session()->regenerate();\App\Services\Settings::audit($r->user()->id,'owner_signed_in',$r->path());return redirect('/admin.html');}
 public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);$key='login:'.sha1(strtolower($v['email']).'|'.$r->ip());if(RateLimiter::tooManyAttempts($key,5))return back()->withErrors(['email'=>'Too many attempts. Try again in 15 minutes.']);if(!config('app.preview')&&User::where('email',strtolower($v['email']))->where('is_admin',true)->exists()){RateLimiter::hit($key,900);return back()->withErrors(['email'=>'Email or password is incorrect.']);}if(!Auth::attempt(['email'=>strtolower($v['email']),'password'=>$v['password'],'blocked'=>false],false)){RateLimiter::hit($key,900);return back()->withErrors(['email'=>'Email or password is incorrect.']);}RateLimiter::clear($key);$r->session()->regenerate();$next=(string)$r->input('next','');$safe=$next!==''&&$next[0]==='/'&&!str_starts_with($next,'//')&&!str_contains($next,'\\')&&!preg_match('/[\\x00-\\x1f\\x7f]|%0[0-9a-f]|%2f|%5c/i',$next);if($safe&&(!str_starts_with($next,'/admin')||$r->user()->is_admin))return redirect($next);return redirect($r->user()->is_admin?'/admin.html':'/workspace.html');}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/');}
 public function forgot(Request $r){$r->validate(['email'=>'required|email']);$u=User::where('email',strtolower($r->email))->first();if($u){$token=Password::createToken($u);MailAutomation::queue($u,'password_reset',hash('sha256',$token),['reset_url'=>rtrim((string)config('app.url'),'/').'/reset-password/'.$token.'?email='.urlencode($u->email)],true);}return back()->with('status','If that account exists, a reset link has been queued for delivery.');}
 public function reset(Request $r){$r->validate(['token'=>'required','email'=>'required|email','password'=>'required|string|min:12|max:200|confirmed']);$status=Password::reset($r->only('email','password','password_confirmation','token'),function(User $u,string $p){$u->forceFill(['password'=>Hash::make($p),'remember_token'=>Str::random(60)])->save();DB::table('sessions')->where('user_id',$u->id)->delete();});return $status===Password::PASSWORD_RESET?redirect('/login')->with('status','Password updated. Sign in with your new password.'):back()->withErrors(['email'=>'This reset link is invalid or expired.']);}
}
